local AlchemicalElixirMaker = {}
local PRODUCTS = {
    vitality_elixir = { name = "Eliksir vitalnosti", herbCost = 2, mineralCost = 1, waterCost = 1, time = 3, cost = 50, potency = 40, prestige = 3, description = "Eliksir vitalnosti za obnovo moči." },
    longevity_elixir = { name = "Eliksir dolgoživosti", herbCost = 3, mineralCost = 1, silverCost = 1, waterCost = 1, time = 5, cost = 120, potency = 55, prestige = 6, happiness = 1, description = "Eliksir za podaljšanje življenja." },
    wisdom_elixir = { name = "Eliksir modrosti", herbCost = 3, mineralCost = 2, silverCost = 1, goldCost = 1, time = 8, cost = 300, potency = 70, prestige = 12, happiness = 2, description = "Eliksir modrosti za učenjake." },
    silver_cauldron_elixir = { name = "Srebrnolončni eliksir", herbCost = 4, mineralCost = 2, silverCost = 1, goldCost = 1, waterCost = 1, time = 11, cost = 680, potency = 82, prestige = 20, happiness = 3, description = "Eliksir iz srebrnega kotla za plemiče." },
    gold_cauldron_elixir = { name = "Zlatožbronasti eliksir", herbCost = 5, mineralCost = 2, goldCost = 2, silverCost = 1, jewelCost = 1, waterCost = 1, time = 14, cost = 1400, potency = 92, prestige = 30, happiness = 6, description = "Eliksir iz zlatega kotla za visoke plemiče." },
    royal_grand_elixir = { name = "Kraljevski veliki eliksir", herbCost = 8, mineralCost = 3, goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 1, waterCost = 2, time = 20, cost = 3500, potency = 100, prestige = 60, happiness = 13, description = "Veliki kraljevski eliksir z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Eliksirska delavnica", cost = { gold = 350, wood = 140, stone = 300 }, upkeep = 9, qualityBonus = 5 },
    alchemy_chamber = { name = "Alkemijska komora", cost = { gold = 1200, wood = 300, stone = 600, herb = 10 }, upkeep = 30, qualityBonus = 18 },
    distillation_room = { name = "Destilacijska soba", cost = { gold = 2800, wood = 400, stone = 800, silver = 40, glass = 8 }, upkeep = 70, qualityBonus = 30 },
    royal_elixir_atelier = { name = "Kraljevski atelje eliksirjev", cost = { gold = 12000, wood = 700, stone = 1200, gold = 80, jewel = 25 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
AlchemicalElixirMaker.herbStock = 22; AlchemicalElixirMaker.mineralStock = 14; AlchemicalElixirMaker.waterStock = 18; AlchemicalElixirMaker.silverStock = 8; AlchemicalElixirMaker.goldStock = 6; AlchemicalElixirMaker.jewelStock = 6; AlchemicalElixirMaker.pearlStock = 4
AlchemicalElixirMaker.productStock = {}; AlchemicalElixirMaker.buildings = {}; AlchemicalElixirMaker.maker = nil; AlchemicalElixirMaker.activeMaking = {}; AlchemicalElixirMaker.totalProducts = 0; AlchemicalElixirMaker.dayTimer = 0
function AlchemicalElixirMaker.init() AlchemicalElixirMaker.herbStock=22; AlchemicalElixirMaker.mineralStock=14; AlchemicalElixirMaker.waterStock=18; AlchemicalElixirMaker.silverStock=8; AlchemicalElixirMaker.goldStock=6; AlchemicalElixirMaker.jewelStock=6; AlchemicalElixirMaker.pearlStock=4; AlchemicalElixirMaker.productStock={}; AlchemicalElixirMaker.buildings={}; AlchemicalElixirMaker.maker=nil; AlchemicalElixirMaker.activeMaking={}; AlchemicalElixirMaker.totalProducts=0; AlchemicalElixirMaker.dayTimer=0; print("[AlchemicalElixirMaker] Royal Alchemical Elixir Maker System initialized (6 products, 4 buildings)") end
function AlchemicalElixirMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AlchemicalElixirMaker.maker={name=n or ("Alkemičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Alkemičar najet: %s (spretnost: %d)",AlchemicalElixirMaker.maker.name,s),"success") end; return true end
function AlchemicalElixirMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AlchemicalElixirMaker.build(id) local ok,e=AlchemicalElixirMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AlchemicalElixirMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AlchemicalElixirMaker.getQualityBonus() local b=0; for _,bd in ipairs(AlchemicalElixirMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AlchemicalElixirMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.herbCost and AlchemicalElixirMaker.herbStock<(d.herbCost or 0) then return false,"Premalo zelišč" end; if d.mineralCost and AlchemicalElixirMaker.mineralStock<(d.mineralCost or 0) then return false,"Premalo mineralov" end; if d.waterCost and AlchemicalElixirMaker.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.silverCost and AlchemicalElixirMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AlchemicalElixirMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AlchemicalElixirMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AlchemicalElixirMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AlchemicalElixirMaker.buildings==0 then return false,"Potrebna delavnica" end; if not AlchemicalElixirMaker.maker then return false,"Potreben alkemičar" end; return true end
function AlchemicalElixirMaker.make(pt,qty) qty=qty or 1; local ok,e=AlchemicalElixirMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.herbCost then AlchemicalElixirMaker.herbStock=AlchemicalElixirMaker.herbStock-d.herbCost*qty end; if d.mineralCost then AlchemicalElixirMaker.mineralStock=AlchemicalElixirMaker.mineralStock-d.mineralCost*qty end; if d.waterCost then AlchemicalElixirMaker.waterStock=AlchemicalElixirMaker.waterStock-d.waterCost*qty end; if d.silverCost then AlchemicalElixirMaker.silverStock=AlchemicalElixirMaker.silverStock-d.silverCost*qty end; if d.goldCost then AlchemicalElixirMaker.goldStock=AlchemicalElixirMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AlchemicalElixirMaker.jewelStock=AlchemicalElixirMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AlchemicalElixirMaker.pearlStock=AlchemicalElixirMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AlchemicalElixirMaker.maker then t=math.max(1,t-math.floor(AlchemicalElixirMaker.maker.skill/12)) end; table.insert(AlchemicalElixirMaker.activeMaking,{id="elixir_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,potency=d.potency or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AlchemicalElixirMaker.completeMaking(m) local q=1.0+(AlchemicalElixirMaker.getQualityBonus()/100); if AlchemicalElixirMaker.maker then q=q+(AlchemicalElixirMaker.maker.skill/150) end; q=math.min(2.5,q); AlchemicalElixirMaker.productStock[m.productType]=(AlchemicalElixirMaker.productStock[m.productType] or 0)+m.quantity; AlchemicalElixirMaker.totalProducts=AlchemicalElixirMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AlchemicalElixirMaker.maker then AlchemicalElixirMaker.maker.itemsMade=AlchemicalElixirMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then AlchemicalElixirMaker.maker.skill=math.min(100,AlchemicalElixirMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Eliksir izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"elixir.completed",{productName=m.productName,potency=m.potency,prestige=m.prestige,happiness=m.happiness}) end end
function AlchemicalElixirMaker.update(dt) if not _G.state then return end; AlchemicalElixirMaker.dayTimer=AlchemicalElixirMaker.dayTimer+dt; if AlchemicalElixirMaker.dayTimer>=30 then AlchemicalElixirMaker.dayTimer=0; for i=#AlchemicalElixirMaker.activeMaking,1,-1 do local m=AlchemicalElixirMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AlchemicalElixirMaker.completeMaking(m); table.remove(AlchemicalElixirMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AlchemicalElixirMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AlchemicalElixirMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AlchemicalElixirMaker.getStats() return {herbStock=AlchemicalElixirMaker.herbStock,mineralStock=AlchemicalElixirMaker.mineralStock,waterStock=AlchemicalElixirMaker.waterStock,silverStock=AlchemicalElixirMaker.silverStock,goldStock=AlchemicalElixirMaker.goldStock,jewelStock=AlchemicalElixirMaker.jewelStock,pearlStock=AlchemicalElixirMaker.pearlStock,productStock=AlchemicalElixirMaker.productStock,numBuildings=#AlchemicalElixirMaker.buildings,hasMaker=AlchemicalElixirMaker.maker~=nil,makerName=AlchemicalElixirMaker.maker and AlchemicalElixirMaker.maker.name or "—",makerSkill=AlchemicalElixirMaker.maker and AlchemicalElixirMaker.maker.skill or 0,activeMaking=#AlchemicalElixirMaker.activeMaking,totalProducts=AlchemicalElixirMaker.totalProducts} end
return AlchemicalElixirMaker
